// The HTTP client is generated by Hey API (`npm run gen:api`): one SDK function per operation
// (src/generated/sdk.gen.ts) and TanStack Query options, keys and mutations for each
// (src/generated/@tanstack/react-query.gen.ts). This file configures the one shared client: the
// access token, the `{ ok: 1, data }` envelope (unwrapped here, so callers get `data`), and failures
// (thrown as ApiError).

import { client } from './generated/client.gen.ts';
import type { Message } from './generated/types.gen.ts';

export interface ApiClientOptions {
  /** API origin, e.g. `http://localhost:3000`; '' for same-origin (behind a proxy) */
  baseUrl?: string;
  /** current access token, or null when logged out */
  getToken?: () => string | null | undefined;
  /** called on any 401 answer (expired or revoked token) */
  onUnauthorized?: () => void;
  fetch?: typeof globalThis.fetch;
}

/**
 * A failed call: `code` is the game's (negative) error code, `status` the HTTP status, and `error` what to tell the
 * player, as a message code + params (null when no answer came back, e.g. the network failed). `message` is
 * the code, for logs.
 */
export class ApiError extends Error {
  readonly code: number;
  readonly status: number;
  readonly error: Message | null;
  readonly issues?: { path: string; message?: string }[];
  constructor(code: number, error: Message | null, status: number, issues?: { path: string; message?: string }[]) {
    super(error?.code ?? `HTTP ${status}`);
    this.name = 'ApiError';
    this.code = code;
    this.status = status;
    this.error = error;
    this.issues = issues;
  }
}

interface ErrorBody {
  ok: number;
  error: Message;
  issues?: { path: string; message?: string }[];
}

/** Point the generated client at the API. Call once, before the first request. */
export function configureApi(opts: ApiClientOptions = {}) {
  client.setConfig({ baseUrl: opts.baseUrl ?? '', ...(opts.fetch ? { fetch: opts.fetch } : {}) });
  client.interceptors.request.use((request) => {
    const token = opts.getToken?.();
    if (token) request.headers.set('Authorization', `Bearer ${token}`);
    return request;
  });
  client.interceptors.response.use(async (response) => {
    if (response.status === 401) opts.onUnauthorized?.();
    if (!response.ok) return response;
    // `{ ok: 1, data }` -> `data` (null for commands without a result)
    const body = (await response.clone().json()) as { ok?: number; data?: unknown };
    const headers = new Headers(response.headers);
    headers.delete('content-length');
    return new Response(JSON.stringify(body.data ?? null), { status: response.status, statusText: response.statusText, headers });
  });
  client.interceptors.error.use((error, response) => {
    if (error instanceof ApiError) return error;
    const body = error as Partial<ErrorBody> | undefined;
    return new ApiError(body?.ok ?? -99, body?.error ?? null, response?.status ?? 0, body?.issues);
  });
}
